def wrap(text, width, indent=""):
    """Wrap `text` to lines of at most `width` characters. See TASK.md.

    Returns a list of lines (list[str]) with no newline characters.
    """
    # Rule 6: validate arguments.
    if not isinstance(width, int) or isinstance(width, bool):
        raise ValueError("width must be an int of at least 1")
    if width < 1:
        raise ValueError("width must be an int of at least 1")
    if not isinstance(indent, str):
        raise ValueError("indent must be a string")
    if len(indent) >= width:
        raise ValueError("indent must be shorter than width")

    def wrap_paragraph(para):
        # Rule 2: words are maximal runs of non-whitespace.
        words = para.split()
        # Rule 1: a paragraph with no words gives exactly one empty line.
        if not words:
            return [""]

        result = []
        is_first = [True]   # True for the first line of the paragraph
        current = [""]       # content of the line being built (no indent yet)

        def capacity():
            # Rule 4: the first line has no indent; later lines start with
            # indent, and the indent counts toward width.
            return width if is_first[0] else width - len(indent)

        def finish_line():
            line = current[0] if is_first[0] else indent + current[0]
            result.append(line)
            current[0] = ""
            is_first[0] = False

        def place_on_empty(word):
            c = capacity()
            if len(word) <= c:
                # The whole word fits on this empty line.
                current[0] = word
            else:
                # Rule 5: fill the empty line with as much of the word as
                # fits, then continue the rest on the next line.
                current[0] = word[:c]
                finish_line()
                rest = word[c:]
                while rest:
                    c = capacity()  # always >= 1 because indent < width
                    if len(rest) <= c:
                        current[0] = rest
                        rest = ""
                    else:
                        current[0] = rest[:c]
                        finish_line()
                        rest = rest[c:]

        for word in words:
            if current[0]:
                # Rule 3: try to fit the word on the current line, joined by
                # one space (rule 2).
                if len(current[0]) + 1 + len(word) <= capacity():
                    current[0] = current[0] + " " + word
                else:
                    # The word does not fit; start a new line (rule 3/5).
                    finish_line()
                    place_on_empty(word)
            else:
                place_on_empty(word)

        # Flush the last line being built.
        if current[0]:
            finish_line()

        return result

    lines = []
    # Rule 1: split at every "\n"; each piece is a paragraph.
    for para in text.split("\n"):
        lines.extend(wrap_paragraph(para))
    return lines
